const storageKey='conductor-workspace-v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch(e){}
let projects=Array.isArray(saved.projects)?saved.projects:defaultProjects.map(x=>({...x}));
let missions=Array.isArray(saved.missions)?saved.missions:seedMissions.map(x=>({...x}));
let currentView='overview', projectFilter=null, statusFilter='all', weekOffset=0;
function save(){try{localStorage.setItem(storageKey,JSON.stringify({projects,missions}))}catch(e){toast('No se pudo guardar en este navegador.')}}
function project(id){return projects.find(p=>p.id===id)||{name:'Sin proyecto',color:'#b8c2b9'}}
function agent(id){return agents.find(a=>a.id===id)||agents[0]}
function visibleMissions(){return missions.filter(m=>(!projectFilter||m.project===projectFilter)&&(statusFilter==='all'||m.status===statusFilter))}
const statusLabel={progress:'En progreso',planned:'Planificada',done:'Completada'};
function renderProjects(){
 $('#projectNav').innerHTML=projects.map(p=>`<button class="project-link ${projectFilter===p.id?'selected':''}" data-project="${esc(p.id)}"><span class="project-dot" style="background:${esc(p.color)}"></span>${esc(p.name)}</button>`).join('');
 $('#projectSelect').innerHTML=projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');
}
function renderMetrics(){let active=missions.filter(m=>m.status==='progress'||m.status==='planned').length,done=missions.filter(m=>m.status==='done').length;$('#activeCount').innerHTML=`${String(active).padStart(2,'0')} <span class="metric-trend">↗ en marcha</span>`;$('#doneCount').innerHTML=`${String(done).padStart(2,'0')} <span class="metric-trend">↗ buen ritmo</span>`;$('#navMissionCount').textContent=missions.length;$('#missionCount').textContent=String(visibleMissions().length).padStart(2,'0')}
function renderMissions(){const list=visibleMissions();const shown=currentView==='overview'?list.slice(0,4):list;$('#missionList').innerHTML=shown.length?shown.map(m=>{let p=project(m.project),a=agent(m.agent);return `<div class="mission-row"><button class="mission-check ${m.status==='done'?'done':''}" data-check="${esc(m.id)}" aria-label="${m.status==='done'?'Reabrir':'Completar'} ${esc(m.title)}">${m.status==='done'?icon('check'):''}</button><div><div class="mission-title">${esc(m.title)}</div><div class="mission-project"><span class="project-dot" style="background:${esc(p.color)}"></span>${esc(p.name)}</div></div><span class="status-badge ${esc(m.status)}">${statusLabel[m.status]||'Planificada'}</span><span class="mission-date">${esc(m.horizon)}</span><span class="mini-avatar" title="${esc(a.name)}" style="background:${a.bg};color:${a.fg}">${esc(a.id)}</span></div>`}).join(''):'<div class="empty-state">No hay misiones en esta vista. Crea una para comenzar.</div>';$('#missionsSection .panel-bottom-link').style.display=currentView==='overview'?'block':'none'}
function renderGantt(){let now=new Date(), monday=new Date(now);monday.setHours(0,0,0,0);monday.setDate(now.getDate()-(now.getDay()+6)%7+weekOffset*7);let days=['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'];let heads=days.map((d,i)=>{let day=new Date(monday);day.setDate(monday.getDate()+i);return `<span class="${day.toDateString()===now.toDateString()?'today':''}">${d} ${String(day.getDate()).padStart(2,'0')}</span>`}).join('');let list=visibleMissions().filter(m=>m.status!=='done').slice(0,currentView==='timeline'?10:5);$('#gantt').innerHTML=`<div class="gantt-header"><span>MISIÓN</span>${heads}</div>`+(list.length?list.map((m,i)=>{let p=project(m.project),start=weekOffset===0?(m.start||1):m.horizon==='Próxima semana'?1:m.loop?1:0;if(!start)return `<div class="gantt-row"><div class="gantt-name"><span class="project-dot" style="background:${esc(p.color)}"></span>${esc(m.title)}</div><div class="gantt-track"></div></div>`;let length=Math.min(m.length||3,8-start);let type=m.loop?'loop':m.status;return `<div class="gantt-row"><div class="gantt-name" title="${esc(m.title)}"><span class="project-dot" style="background:${esc(p.color)}"></span>${esc(m.title)}</div><div class="gantt-track"><div class="gantt-bar ${type}" style="grid-column:${start} / span ${length}">${m.loop?'↻ Diario':m.status==='planned'?'Planificada':'En progreso'}</div></div></div>`}).join(''):'<div class="empty-state">No hay misiones para mostrar en el timeline.</div>');$('#timelineToggle span').textContent=weekOffset?'Próxima semana':'Esta semana'}
function renderAgents(){$('#agentsList').innerHTML=agents.map(a=>`<div class="agent-row"><div class="agent-avatar" style="background:${a.bg};color:${a.fg}">${a.id}</div><div class="agent-details"><strong>${a.name}</strong><small>${a.role}</small></div><span class="agent-state ${a.state==='En espera'?'idle':''}">${a.state}</span></div>`).join('')}
function renderActivity(){const items=[['check-circle','Luna','actualizó la dirección del proyecto','Hace 12 min'],['sparkles','Nova','compartió nuevas referencias','Hace 1 hora'],['activity','Orbit','completó su revisión diaria','Hace 2 horas']];$('#activityList').innerHTML=items.map(([ico,name,text,time])=>`<div class="activity-item"><div class="activity-icon">${icon(ico)}</div><div><p><strong>${name}</strong> ${text}</p><small>${time}</small></div></div>`).join('')}
function render(){renderProjects();renderMetrics();renderMissions();renderGantt();renderAgents();renderActivity();$('#filterButton span').textContent=statusFilter==='all'?'Todas':statusLabel[statusFilter]}
function setView(view){currentView=view;projectFilter=null;statusFilter='all';const titles={overview:['Overview','Todo en movimiento','Una vista compartida de todo lo que tu equipo está construyendo.'],missions:['Misiones','Cada misión cuenta','Organiza los próximos pasos de tu equipo en un solo lugar.'],timeline:['Timeline','El camino por delante','Una mirada al trabajo que viene y cómo se conecta.'],agents:['Agentes','Un equipo en sintonía','Conoce a los agentes que hacen avanzar tus proyectos.']};let t=titles[view]||titles.overview;$('#breadcrumb').textContent=t[0];$('#pageTitle').innerHTML=esc(t[1])+'<span>.</span>';$('#pageSubtitle').textContent=t[2];document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#timelineSection').style.display=(view==='overview'||view==='timeline')?'':'none';$('#missionsSection').style.display=(view==='overview'||view==='missions')?'':'none';$('#agentsSection').style.display=(view==='overview'||view==='agents')?'':'none';$('.activity-panel').style.display=(view==='overview'||view==='agents')?'':'none';$('.quote-card').style.display=(view==='overview'||view==='agents')?'':'none';$('.content-grid').classList.toggle('single-view',view==='missions'||view==='timeline');$('.content-side').style.display=(view==='missions'||view==='timeline')?'none':'';$('#sidebar').classList.remove('open');render()}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}

