function renderMonthTrack() {
  const el = $('#monthTrack');
  if (!el) return;
  const items = state.missions
    .filter(m => m.horizon === 'month' && isOpen(m))
    .sort((a, b) => (a.startDay || 0) - (b.startDay || 0));
  el.innerHTML = items.length ? items.map(m => {
