320:       else if (action.type === 'updateCard' && action.data?.listAfter) text = `Movió “${action.data.card?.name || 'una carta'}” a ${action.data.listAfter.name}`;
321:       else if (action.type === 'createCard') text = `Creó “${action.data?.card?.name || 'una carta'}”`;
322:       return {
323:         id: action.id,
324:         type: action.type,
325:         member: action.memberCreator?.fullName || action.memberCreator?.username || 'Trello',
326:         text,
327:         date: action.date
328:       };
329:     }).filter(a => a.text);
330:     trello = { live: true, lists, cards, actions, updatedAt: Date.now(), error: null };
