41: function pulseGraphSVG() {
42:   const bins = Array(15).fill(0);
43:   state.activity.forEach(e => {
44:     const idx = clamp(Math.floor((REPLAY_DURATION - e.agoSeconds) / 60), 0, 14);
45:     bins[idx] += 1;
46:   });
47:   const max = Math.max(2, ...bins);
48:   const width = 300, height = 78, base = 66, step = 20;
49:   const points = bins.map((count, i) => {
50:     const x = 6 + i * step;
51:     const y = base - (count / max) * 43;
52:     return [x, y, count];
53:   });
54:   let line = `M ${points[0][0]},${points[0][1]}`;
55:   for (let i = 1; i < points.length; i++) {
56:     const prev = points[i - 1], cur = points[i];
57:     const mid = (prev[0] + cur[0]) / 2;
58:     line += ` C ${mid},${prev[1]} ${mid},${cur[1]} ${cur[0]},${cur[1]}`;
59:   }
60:   const area = `${line} L${points[points.length - 1][0]},${height} L${points[0][0]},${height} Z`;
61:   const dots = points.filter(p => p[2] > 0).map(([x, y]) => `<circle cx="${x}" cy="${y}" r="1.15" fill="#d4e9bf" opacity=".7"/>`).join('');
62:   return `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Densidad de actividad en los últimos 15 minutos">
63:     <defs>
64:       <linearGradient id="pulseArea" x1="0" y1="0" x2="0" y2="1">
65:         <stop offset="0" stop-color="#b9dba0" stop-opacity=".28"/>
66:         <stop offset="1" stop-color="#b9dba0" stop-opacity="0"/>
67:       </linearGradient>
68:     </defs>
69:     <line x1="4" y1="${base}" x2="${width - 4}" y2="${base}" stroke="rgba(214,235,201,.14)" stroke-width=".7"/>
70:     <path d="${area}" fill="url(#pulseArea)"/>
71:     <path d="${line}" fill="none" stroke="#c8e3b1" stroke-width="1.35" stroke-linejoin="round" opacity=".92" vector-effect="non-scaling-stroke"/>
72:     ${dots}
73:     <line x1="${width - 8}" y1="20" x2="${width - 8}" y2="${base + 3}" stroke="rgba(218,238,204,.26)" stroke-width=".7" stroke-dasharray="2 3"/>
74:     <circle cx="${width - 8}" cy="${points[14][1]}" r="1.8" fill="#e4f2d7"/>
75:   </svg>`;
76: }
