25:     const event = currentEventFor(agent.id, at);
26:     const base = event?.spot || agent.home || { x: 50, y: 55 };
27:     let spot = { ...base };
28:     let tries = 0;
29:     while (tries < offsets.length && placed.some(p => Math.abs(p.x - spot.x) < 14 && Math.abs(p.y - spot.y) < 13)) {
30:       spot = { x: base.x + offsets[tries][0], y: base.y + offsets[tries][1] };
31:       tries++;
32:     }
33:     spot.x = clamp(spot.x, 20, 80);
34:     spot.y = clamp(spot.y, 30, 72);
35:     placed.push(spot);
36:     spots.set(agent.id, spot);
37:   });
38:   return spots;
