164:   const cacheKey = `conductor.github.${repo}`;
165:   if (!show) {
166:     try {
167:       const cached = JSON.parse(sessionStorage.getItem(cacheKey) || 'null');
168:       if (cached && Date.now() - cached.time < 120000) {
169:         github = { ...cached.data, live: true };
170:         syncMeta.githubAt = cached.data.updatedAt || cached.time;
171:         renderGithubSource();
172:         if (currentView === 'home') renderHomeIssues();
