189:   if (seconds == null && agent.lastHeartbeat) seconds = (Date.now() - new Date(agent.lastHeartbeat).getTime()) / 1000;
190:   const status = seconds == null ? 'stale' : seconds <= threshold ? 'fresh' : 'stale';
