86: function isoWeek(date) {
87:   const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
88:   const dayNum = (d.getUTCDay() + 6) % 7;
89:   d.setUTCDate(d.getUTCDate() - dayNum + 3);
90:   const firstThursday = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
91:   return 1 + Math.round(((d - firstThursday) / 86400000 - 3 + ((firstThursday.getUTCDay() + 6) % 7)) / 7);
