158: async function syncGitHub(show = true) {
159:   const repo = (connections.githubRepo || state.workspace.repo || '').replace(/^https?:\/\/github.com\//, '').replace(/\/$/, '');
160:   if (!repo.includes('/')) {
161:     if (show) toast('El repo debe tener formato owner/repo.');
162:     return false;
163:   }
164:   const cacheKey = `conductor.github.${repo}`;
165:   if (!show) {
166:     try {
167:       const cached = JSON.parse(sessionStorage.getItem(cacheKey) || 'null');
168:       if (cached && Date.now() - cached.time < 120000) {
169:         github = { ...cached.data, live: true };
170:         syncMeta.githubAt = cached.data.updatedAt || cached.time;
171:         renderGithubSource();
172:         if (currentView === 'home') renderHomeIssues();
173:         if (currentView === 'missions') { renderMissionList(); renderGithubIssues(); }
174:         if (typeof renderSyncStatus === 'function') renderSyncStatus();
175:         return true;
176:       }
177:     } catch (_) {}
178:   }
179:   const headers = { Accept: 'application/vnd.github+json' };
180:   if (connections.githubToken) headers.Authorization = `Bearer ${connections.githubToken}`;
181:   try {
182:     const res = await fetch(`https://api.github.com/repos/${repo}/issues?state=all&per_page=30&sort=updated`, { headers });
183:     if (!res.ok) throw new Error(res.status === 404 ? 'Repo no encontrado' : res.status === 403 ? 'Límite de GitHub alcanzado' : `GitHub respondió ${res.status}`);
184:     const issues = await res.json();
185:     if (!Array.isArray(issues)) throw new Error('Respuesta inválida');
186:     const data = { repo, issues, updatedAt: Date.now(), error: null };
187:     github = { ...data, live: true };
188:     syncMeta.githubAt = data.updatedAt;
189:     try { sessionStorage.setItem(cacheKey, JSON.stringify({ time: Date.now(), data })); } catch (_) {}
190:     renderGithubSource();
191:     if (currentView === 'home') renderHomeIssues();
192:     if (currentView === 'missions') { renderMissionList(); renderGithubIssues(); }
193:     if (typeof renderSyncStatus === 'function') renderSyncStatus(); else renderSidebar();
194:     if (show) toast(`GitHub sincronizado · ${issues.filter(i => !i.pull_request).length} issues`);
195:     return true;
196:   } catch (err) {
197:     github.live = false;
198:     github.error = err.message;
199:     renderGithubSource();
200:     if (typeof renderSyncStatus === 'function') renderSyncStatus();
201:     if (show) toast(`GitHub: ${err.message}. Sigo con el snapshot del repo.`);
202:     return false;
203:   }
204: }
