307:   const { trelloKey: key, trelloToken: token, trelloBoard: board } = connections;
308:   if (!key || !token || !board) {
309:     trello = { ...trello, live: false };
310:     renderTrelloBoard();
311:     if (show) toast('Completá key, token y board ID para conectar Trello.');
312:     return false;
313:   }
314:   const base = `https://api.trello.com/1/boards/${encodeURIComponent(board)}`;
315:   const auth = `key=${encodeURIComponent(key)}&token=${encodeURIComponent(token)}`;
316:   try {
317:     const [listsRes, actionsRes] = await Promise.all([
318:       fetch(`${base}/lists?cards=open&card_fields=name,desc,idList,dateLastActivity,labels,shortUrl&${auth}`),
319:       fetch(`${base}/actions?filter=commentCard,updateCard,createCard&limit=20&fields=type,date,data&memberCreator=true&memberCreator_fields=fullName,username,initials&${auth}`)
320:     ]);
321:     if (!listsRes.ok) throw new Error(listsRes.status === 401 ? 'credenciales inválidas' : `Trello respondió ${listsRes.status}`);
322:     const lists = await listsRes.json();
323:     if (!Array.isArray(lists)) throw new Error('Respuesta de tablero inválida');
324:     const actionsRaw = actionsRes.ok ? await actionsRes.json() : [];
325:     const cards = lists.flatMap(l => (l.cards || []).map(c => ({ ...c, idList: l.id })));
326:     const actions = (Array.isArray(actionsRaw) ? actionsRaw : []).map(action => {
327:       let text = '';
328:       if (action.type === 'commentCard') text = action.data?.text || 'Dejó un comentario';
329:       else if (action.type === 'updateCard' && action.data?.listAfter) text = `Movió “${action.data.card?.name || 'una carta'}” a ${action.data.listAfter.name}`;
330:       else if (action.type === 'createCard') text = `Creó “${action.data?.card?.name || 'una carta'}”`;
331:       return {
332:         id: action.id,
333:         type: action.type,
334:         member: action.memberCreator?.fullName || action.memberCreator?.username || 'Trello',
335:         text,
336:         date: action.date
337:       };
338:     }).filter(a => a.text);
339:     trello = { live: true, lists, cards, actions, updatedAt: Date.now(), error: null };
340:     syncMeta.trelloAt = trello.updatedAt;
341:     renderTrelloBoard();
342:     renderWorldMachine();
343:     renderMachinePreview();
344:     if (typeof renderSyncStatus === 'function') renderSyncStatus(); else renderSidebar();
345:     if (show) toast(`Trello conectado · ${cards.length} cartas en ${lists.length} listas`);
346:     return true;
347:   } catch (err) {
348:     trello.live = false;
349:     trello.error = err.message;
350:     renderTrelloBoard();
351:     if (typeof renderSyncStatus === 'function') renderSyncStatus();
352:     if (show) toast(`Trello: ${err.message}. El tablero sigue en modo demo.`);
353:     return false;
354:   }
355: }
